/* GitHub Theme - Official GitHub brand colors (Primer Design System)  */

/* Light mode */
[data-theme="github-light"] {
  --background: rgb(255, 255, 255);
  --foreground: rgb(28, 34, 41);
  --card: rgb(247, 249, 250);
  --card-foreground: rgb(28, 34, 41);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(28, 34, 41);
  --primary: rgb(16, 120, 35);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(239, 242, 245);
  --secondary-foreground: rgb(40, 47, 53);
  --muted: rgb(244, 245, 247);
  --muted-foreground: rgb(93, 100, 108);
  --accent: rgb(48, 114, 223);
  --accent-foreground: rgb(255, 255, 255);
  --destructive: rgb(204, 39, 46);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(208, 213, 217);
  --input: rgb(244, 245, 247);
  --ring: rgb(48, 114, 223);
  --chart-1: rgb(16, 120, 35);
  --chart-2: rgb(48, 114, 223);
  --chart-3: rgb(183, 110, 199);
  --chart-4: rgb(221, 131, 100);
  --chart-5: rgb(0, 149, 131);
  --radius: 0.375rem;
  --sidebar: rgb(244, 245, 247);
  --sidebar-foreground: rgb(28, 34, 41);
  --sidebar-primary: rgb(16, 120, 35);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(239, 242, 245);
  --sidebar-accent-foreground: rgb(40, 47, 53);
  --sidebar-border: rgb(208, 213, 217);
  --sidebar-ring: rgb(48, 114, 223);
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  --shadow-color: rgb(41, 49, 61);
  --shadow-opacity: 0.06;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 0 0px hsl(215 20% 20% / 0.04);
  --shadow-xs: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 1px 3px 0px hsl(215 20% 20% / 0.06);
  --shadow-sm: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
  --shadow: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
  --shadow-md: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 4px 8px 0px hsl(215 20% 20% / 0.1);
  --shadow-lg: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 8px 16px 0px hsl(215 20% 20% / 0.1);
  --shadow-xl: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 12px 28px 0px hsl(215 20% 20% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(215 20% 20% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #0D1117 is GitHub's signature dark background */
[data-theme="github-dark"] {
  --background: rgb(8, 12, 16);
  --foreground: rgb(201, 206, 212);
  --card: rgb(14, 18, 23);
  --card-foreground: rgb(201, 206, 212);
  --popover: rgb(18, 23, 27);
  --popover-foreground: rgb(201, 206, 212);
  --primary: rgb(39, 135, 51);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(22, 27, 32);
  --secondary-foreground: rgb(185, 190, 196);
  --muted: rgb(19, 22, 26);
  --muted-foreground: rgb(117, 123, 129);
  --accent: rgb(48, 114, 223);
  --accent-foreground: rgb(255, 255, 255);
  --destructive: rgb(215, 71, 69);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(42, 46, 51);
  --input: rgb(14, 18, 23);
  --ring: rgb(48, 114, 223);
  --chart-1: rgb(39, 135, 51);
  --chart-2: rgb(48, 114, 223);
  --chart-3: rgb(196, 128, 212);
  --chart-4: rgb(238, 147, 115);
  --chart-5: rgb(0, 166, 146);
  --radius: 0.375rem;
  --sidebar: rgb(5, 8, 11);
  --sidebar-foreground: rgb(201, 206, 212);
  --sidebar-primary: rgb(39, 135, 51);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(22, 27, 32);
  --sidebar-accent-foreground: rgb(185, 190, 196);
  --sidebar-border: rgb(42, 46, 51);
  --sidebar-ring: rgb(48, 114, 223);
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.4;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 0 0 1px hsl(0 0% 0% / 0.3);
  --shadow-xs: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 1px 3px 0px hsl(0 0% 0% / 0.3);
  --shadow-sm: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
  --shadow: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
  --shadow-md: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 4px 8px 0px hsl(0 0% 0% / 0.4);
  --shadow-lg: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 8px 16px 0px hsl(0 0% 0% / 0.4);
  --shadow-xl: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 12px 28px 0px hsl(0 0% 0% / 0.5);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
}
